const raw = $input.first().json;
const i = raw.body || raw;
const items = (i.items||i.cart_items||[]).map(x => (x.name||x.product_name||'Article') + ' (x' + (x.quantity||1) + ')').join(', ');
return [{ json: { store_id: i.store_id||1, customer_id: i.customer_id||i.customerId||null, email: i.email||i.customer_email, first_name: i.first_name||i.firstName||'', cart_id: i.cart_id||i.cartId||'cart-'+Date.now(), total: i.total||i.cart_total||0, items_summary: items, items_count: (i.items||i.cart_items||[]).length, abandoned_at: new Date().toISOString() } }];

const response = $input.first().json?.response || 'Objet: Votre panier vous attend\n\nBonjour, vous avez oublié des articles dans votre panier.';
const lines = response.split('\n');
const subject = (lines[0] || '').replace(/^Objet:\s*/i, '') || 'Votre panier vous attend';
const body = lines.slice(1).join('\n').trim() || response;
const cart = $('Normalize Cart').first().json;
return [{ json: { store_id: cart.store_id, from_addr: 'noreply@shimmer.tymmerc.eu', subject: subject.replace(/'/g,"''"), body: body.replace(/'/g,"''").substring(0,2000), to_addr: cart.email, cart_id: cart.cart_id, email_number: 1 } }];

const response = $input.first().json?.response || 'Objet: -10% sur votre panier\n\nUtilisez COMEBACK10.';
const lines = response.split('\n');
const subject = (lines[0]||'').replace(/^Objet:\s*/i,'') || '-10% sur votre panier';
const body = lines.slice(1).join('\n').trim() || response;
const cart = $('Normalize Cart').first().json;
return [{ json: { store_id: cart.store_id, from_addr: 'noreply@shimmer.tymmerc.eu', subject: subject.replace(/'/g,"''"), body: body.replace(/'/g,"''").substring(0,2000), email_number: 2 } }];
